public final class BankAccount {
    private long balanceCents; // never exposed, never double
    private Status status;

    public BankAccount(long openingBalanceCents) {
        if (openingBalanceCents < 0) throw new IllegalArgumentException("negative opening balance");
        this.balanceCents = openingBalanceCents;
        this.status = Status.ACTIVE;
    }

    public synchronized void withdraw(long amountCents) {
        if (amountCents <= 0) throw new IllegalArgumentException("amount must be positive");
        if (status != Status.ACTIVE) throw new IllegalStateException("not active: " + status);
        if (amountCents > balanceCents) throw new IllegalStateException("insufficient funds");
        balanceCents -= amountCents; // single mutation point
    }

    public synchronized void close() {
        if (balanceCents != 0) throw new IllegalStateException("drain before close");
        status = Status.CLOSED;
    }

    public synchronized long getBalanceCents() {
        return balanceCents; // primitive: safe copy by value
    }
}
